const body = $('Webhook').first().json.body || {};
const UP = body.updates || [];
if (!Array.isArray(UP) || !UP.length) throw new Error('No updates array in webhook body');

const R = $json.valueRanges || [];
const pick = (n) => (R.find(x => String(x.range||'').indexOf(n) === 0) || {}).values || [];
const crit = pick('INVESTOR_CRITERIA');
const inv  = pick('INVESTORS!');
if (!crit.length || !inv.length) throw new Error('Read failed: ' + R.map(x=>x.range).join(' , '));

const g = (row,i) => (row && row[i] != null) ? String(row[i]).trim() : '';
const critByRow = {};
crit.forEach((r,i) => { const k = g(r,0); if (k) critByRow[k] = i + 1; });

// field -> [sheet, column letter, column index]
const INV_MAP = { s:['INVESTORS','E',4], g:['INVESTORS','F',5], c:['INVESTORS','G',6] };
const CR_MAP  = { m:['INVESTOR_CRITERIA','G',6], si:['INVESTOR_CRITERIA','H',7],
                  lo:['INVESTOR_CRITERIA','L',11], hi:['INVESTOR_CRITERIA','M',12],
                  cm:['INVESTOR_CRITERIA','N',13], arr:['INVESTOR_CRITERIA','O',14],
                  geo:['INVESTOR_CRITERIA','T',19], th:['INVESTOR_CRITERIA','V',21],
                  ev:['INVESTOR_CRITERIA','W',22], cf:['INVESTOR_CRITERIA','Y',24] };

const data = [], wrote = [], skipped = [], problems = [];

for (const u of UP) {
  const n = parseInt(u.r, 10);
  const ivRow = (n > 1 && n <= inv.length) ? inv[n-1] : null;
  if (!ivRow || !g(ivRow,0)) { problems.push(n + ' :: no INVESTORS row'); continue; }
  const name = g(ivRow,0);
  const cRow = critByRow[String(n)];
  const cArr = cRow ? crit[cRow-1] : null;
  const did = [], skip = [];

  for (const [f, spec] of Object.entries(INV_MAP)) {
    if (u[f] == null) continue;
    if (g(ivRow, spec[2])) { skip.push(f + ' (already set)'); continue; }
    data.push({ range: 'INVESTORS!' + spec[1] + n, values: [[String(u[f])]] });
    did.push(f);
  }
  for (const [f, spec] of Object.entries(CR_MAP)) {
    if (u[f] == null) continue;
    if (!cArr) { skip.push(f + ' (no criteria row)'); continue; }
    if (g(cArr, spec[2])) { skip.push(f + ' (already set)'); continue; }
    data.push({ range: 'INVESTOR_CRITERIA!' + spec[1] + cRow, values: [[String(u[f])]] });
    did.push(f);
  }
  wrote.push({ row: n, investor: name, crit_row: cRow || null, filled: did, left_alone: skip });
  if (skip.length) skipped.push(n + ' ' + name + ' :: ' + skip.join('; '));
}

if (!data.length) throw new Error('Nothing to write - every target cell already had a value');
if (data.length > 400) throw new Error('Guard: refusing ' + data.length + ' cells (cap 400)');

return [{ json: { body: { valueInputOption: 'RAW', data: data }, cells: data.length,
                  investors: wrote.length, wrote: wrote, skipped: skipped, problems: problems } }];

const c = $('Compute').first().json;
const w = $json;
return [{ json: { updatedCells: w.totalUpdatedCells != null ? w.totalUpdatedCells : null,
                  planned_cells: c.cells, investors_touched: c.investors,
                  per_investor: c.wrote, left_alone: c.skipped, problems: c.problems } }];
